/**
 * Build a robust concat compose body for N inputs.
 * - Normalizes video SAR (and optionally fps/scale) before concat
 * - Normalizes audio sample rate and channel layout before concat
 * - Produces a filter_complex that works for arbitrary N
 *
 * @param {string[]} fileUrls  Array of input MP4 URLs in order
 * @param {object}   opts      Optional normalization/encoding settings
 *   opts.targetFps      number | null   (e.g., 25 or 30; null to skip fps)
 *   opts.targetWidth    number | null   (e.g., 1080; null to skip scale)
 *   opts.targetHeight   number | null   (e.g., 1920; null to skip scale)
 *   opts.sampleRate     number          (default 24000)
 *   opts.channels       "mono"|"stereo" (default "mono")
 *   opts.crf            number          (default 20)
 *   opts.preset         string          (default "veryfast")
 *   opts.audioBitrate   string          (default "192k")
 *   opts.outputId       string          (default "youtube-automation/concat_output.mp4")
 */
function buildSpeedUpVideo(fileUrl, speed) {


  const outputId = "youtube-automation/speedUpFinalVideo.mp4"
  return {
    inputs:[
      {
       file_url:fileUrl
      }
    ],
  filters: [
    {
      filter: "[0:v]setpts=PTS/"+speed+"[vout];[0:a]atempo="+speed+"[aout]"
    }
  ],
    outputs: [
      {
        options: [
          { option: "-map", argument: "[vout]" },
          { option: "-map", argument: "[aout]" },
          { option: "-c:v", argument: "libx264" },
          { option: "-preset", argument: String("veryfast") },
          { option: "-crf", argument: String("20") },
          { option: "-c:a", argument: "aac" },
          { option: "-b:a", argument: String("192k") },
          { option: "-movflags", argument: "+faststart" }
        ]
      }
    ],
    global_options: [{ option: "-y" }],
    metadata: { duration: true, filesize: true },
    id: outputId
  };
}

