      `.trim(),
    }
  }
];

// === INPUTS ===
const seg = $('Split Out').item.json.prompt_parsed;
const filterConfig = $('Split Out').item.json.filter_config;
const metaCfg = filterConfig.meta;
const visualCfg = filterConfig.visual_overlays;
const textCfg = filterConfig.text_overlays;
const audioCfg = filterConfig.audio_overlays;
const transitionCfg = filterConfig.transitions_overlays;
const probe = $('Probe Audio').item.json;
const audioUrl = $('Merge1').item.json.audioFilePath;
const dur = probe?.response?.stdout ? JSON.parse(probe.response.stdout)?.audio_duration ?? 10 : 10;

// === BASE CONFIG ===
const meta = metaCfg || {};
const timing = filterConfig.timing || {};
const delay = +meta.delay_seconds || 0;
const chDur = +timing.chapter_transition_duration || 3;
const defScale = meta.default_scale || "600:-1";
const res = meta.resolution || "1920:1080";
const fps = +meta.fps || 30;
const debug = !!meta.enable_debug_overlay;

// === HELPERS ===
const clamp01 = v => Math.min(1, Math.max(0, isNaN(v) ? 1 : +v));
const center = (x = 0, y = 0, txt = false) => {
  const xp = (x / 100).toFixed(4), yp = (-y / 100).toFixed(4);
  return {
    x: txt ? `(W-text_w)/2+(W*${xp})` : `(W-w)/2+(W*${xp})`,
    y: txt ? `(H-text_h)/2+(H*${yp})` : `(H-h)/2+(H*${yp})`
  };
};
const lanczos = s => s?.includes("flags=") ? s : `${s || defScale}:flags=lanczos`;
const match = (o, s) =>
  (!o.segment_targets && !o.scene_types && !o.chapter_numbers) ||
  o.segment_targets?.includes(s.segment_number) ||
  o.scene_types?.includes(s.scene_type) ||
  o.chapter_numbers?.includes(s.chapter_number);

// === OVERLAYS ===
const visual = visualCfg || {};
const texts = textCfg || {};
const overlays = { ...visual, ...texts };

const ovEntries = Object.entries(overlays).sort((a, b) => (a[1].layer || 0) - (b[1].layer || 0));
const inputs = [], ovs = [];
for (const [k, o] of ovEntries) {
  if (o.type === "text" || !match(o, seg) || !o.url) continue;
  const t = o.type || (o.url.toLowerCase().endsWith(".mp4") ? "video" : "image");
  const opt = [];
  if (t === "image") opt.push({ option: "-loop", argument: "1" }, { option: "-t", argument: String(dur) });
  if (t === "video" && o.loop) opt.push({ option: "-stream_loop", argument: "-1" });
  inputs.push({ file_url: o.url, options: opt });
  ovs.push({ key: k, i: inputs.length - 1, o, t });
}
if (!ovs.length) throw new Error("No overlays matched segment.");
inputs.push({ file_url: audioUrl });

// === BACKGROUND MUSIC (auto loop + fade + volume) ===
let bgIdx = null;
let bgConfig = audioCfg.background_music;
if (bgConfig && (!bgConfig.scope || bgConfig.scope === seg.scene_type || bgConfig.scope === "all")) {
  inputs.push({ file_url: bgConfig.url });
  bgIdx = inputs.length - 1;
}

// === FILTER COMPLEX ===
const parts = [];
let cur = null, tmp = 0;

// visuals
for (const { i, o, t } of ovs) {
  const { x, y } = center(o.x_offset_percent || 0, o.y_offset_percent || 0);
  let f = `[${i}:v]scale=${lanczos(o.scale)},setsar=1,setpts=PTS-STARTPTS`;
  if (o.colorkey) f += `,colorkey=${o.colorkey}`;
  if (o.opacity != null && o.opacity < 100)
    f += `,format=rgba,colorchannelmixer=aa=${clamp01(o.opacity / 100)}`;
  f += `[ov${i}]`;
  parts.push(f);
  if (!cur) cur = `ov${i}`;
  else {
    tmp++;
    const next = `tmp${tmp}`;
    parts.push(`[${cur}][ov${i}]overlay=${x}:${y}:format=auto[${next}]`);
    cur = next;
  }
}

// === AUDIO HANDLING ===
const aIdx = inputs.length - (bgIdx !== null ? 2 : 1);
if (bgIdx !== null) {
  const vol = bgConfig.volume ?? 0.2;
  const fadeIn = bgConfig.fade_in ?? 0;
  const fadeOut = bgConfig.fade_out ?? 0;

  // loop background indefinitely, fade, adjust volume
  let bgChain = `[${bgIdx}:a]aloop=loop=-1:size=2e+09,volume=${vol}`;
  if (fadeIn > 0) bgChain += `,afade=t=in:st=0:d=${fadeIn}`;
  if (fadeOut > 0) bgChain += `,afade=t=out:st=${Math.max(0, dur - fadeOut)}:d=${fadeOut}`;
  bgChain += `[bgaud]`;
  parts.push(bgChain);

  // narration stream (with optional delay)
  if (seg.segment_number === 1 && delay > 0) {
    const ms = Math.round(delay * 1000);
    parts.push(`[${aIdx}:a]adelay=${ms}|${ms}[narr_aud]`);
  } else {
    parts.push(`[${aIdx}:a]anull[narr_aud]`);
  }

  // mix both tracks (duration shortest ensures clean exit)
  parts.push(`[narr_aud][bgaud]amix=inputs=2:duration=shortest:dropout_transition=3[aout]`);
} else {
  // narration only
  if (seg.segment_number === 1 && delay > 0) {
    const ms = Math.round(delay * 1000);
    parts.push(`[${aIdx}:a]adelay=${ms}|${ms}[aout]`);
  } else {
    parts.push(`[${aIdx}:a]anull[aout]`);
  }
}

// === CHAPTER ANIMATION (fixed + safe colons) ===
const chapterAnim = transitionCfg.chapter_animation || {};
if (seg.scene_type === "chapter" && chapterAnim?.enable) {
  const mode = chapterAnim.mode || "intro"; // intro | full | intro_and_full
  const introDur = typeof chapterAnim.duration === "number" ? chapterAnim.duration : chDur;
  const persistentOpacity =
    typeof chapterAnim.persistent_opacity === "number"
      ? clamp01(chapterAnim.persistent_opacity / 100)
      : 1;
  const pos = center(chapterAnim.offset?.x || 0, chapterAnim.offset?.y || 0, true);
  const font = chapterAnim.font || "/app/fonts/ComicNeue-BoldItalic.ttf";
  const color = chapterAnim.fontcolor || "white";
  const size = chapterAnim.fontsize || 72;
  const box = chapterAnim.box ? "box=1:" : "";
  const bc = chapterAnim.boxcolor ? `boxcolor=${chapterAnim.boxcolor}:` : "";
  const bb = chapterAnim.boxborderw ? `boxborderw=${chapterAnim.boxborderw}:` : "";

  const prefix = `${box}${bc}${bb}`.replace(/:+$/, ""); // remove trailing colon

  // Determine text source
  const rawText = (() => {
    if (chapterAnim.text_source === "seg.chapter_name" || !chapterAnim.text_source)
      return seg.chapter_name || "";
    if (chapterAnim.text_source.startsWith("literal:"))
      return chapterAnim.text_source.replace(/^literal:/, "");
    if (chapterAnim.text_source.startsWith("meta.")) {
      const key = chapterAnim.text_source.replace(/^meta\./, "");
      return meta[key] || "";
    }
    return seg.chapter_name || "";
  })();
  const t = String(rawText).replace(/'/g, "\\'");

  if (mode === "intro") {
    tmp++;
    const next = `tmp${tmp}`;
    const enableExpr = `between(t,0,${introDur})`;
    parts.push(
      `[${cur}]drawtext=fontfile='${font}':text='${t}':fontcolor=${color}:fontsize=${size}:x=${pos.x}:y=${pos.y}:${prefix}:enable='${enableExpr}'[${next}]`
    );
    cur = next;
  } else if (mode === "full") {
    tmp++;
    const next = `tmp${tmp}`;
    let pc = color;
    if (persistentOpacity < 1 && !String(color).includes("@"))
      pc = `${color}@${persistentOpacity}`;
    parts.push(
      `[${cur}]drawtext=fontfile='${font}':text='${t}':fontcolor=${pc}:fontsize=${size}:x=${pos.x}:y=${pos.y}:${prefix}[${next}]`
    );
    cur = next;
  } else if (mode === "intro_and_full") {
    // Intro
    tmp++;
    const nextIntro = `tmp${tmp}`;
    const enableExpr = `between(t,0,${introDur})`;
    parts.push(
      `[${cur}]drawtext=fontfile='${font}':text='${t}':fontcolor=${color}:fontsize=${size}:x=${pos.x}:y=${pos.y}:${prefix}:enable='${enableExpr}'[${nextIntro}]`
    );
    cur = nextIntro;

    // Persistent
    tmp++;
    const nextPersist = `tmp${tmp}`;
    let pc2 = color;
    if (persistentOpacity < 1 && !String(color).includes("@"))
      pc2 = `${color}@${persistentOpacity}`;
    const persistSize = Math.max(12, Math.round(size * 0.6));
    parts.push(
      `[${cur}]drawtext=fontfile='${font}':text='${t}':fontcolor=${pc2}:fontsize=${persistSize}:x=${pos.x}:y=${pos.y}:${prefix}[${nextPersist}]`
    );
    cur = nextPersist;
  }
}

// === DEBUG OVERLAY ===
if (debug) {
  tmp++;
  const next = `tmp${tmp}`;
  parts.push(
    `[${cur}]drawtext=text='Seg:${seg.segment_number} Ch:${seg.chapter_number} ${seg.scene_type}':x=20:y=H-th-40:fontcolor=white:fontsize=28:box=1:boxcolor=black@0.4[${next}]`
  );
  cur = next;
}

// === FINAL OUTPUT ===
parts.push(
  `[${cur}]scale=${res}:force_original_aspect_ratio=decrease,pad=${res}:(ow-iw)/2:(oh-ih)/2,fps=${fps},setsar=1,format=yuv420p[vout]`
);
parts.push(`[aout]aresample=48000,pan=stereo|c0=c0|c1=c0[aout]`);

const filterComplex = parts.join("; ");

const outputs = [
  {
    options: [
      { option: "-filter_complex", argument: filterComplex },
      { option: "-map", argument: "[vout]" },
      { option: "-map", argument: "[aout]" },
      { option: "-c:v", argument: "libx264" },
      { option: "-preset", argument: meta.preset || "veryfast" },
      { option: "-crf", argument: String(meta.crf || 20) },
      { option: "-c:a", argument: "aac" },
      { option: "-b:a", argument: meta.audioBitrate || "192k" },
      { option: "-ar", argument: "48000" },
      { option: "-ac", argument: "2" },
      { option: "-shortest" },
      { option: "-movflags", argument: "+faststart" }
    ]
  }
];

return {
  compose_request_body: {
    inputs,
    outputs,
    global_options: [
      { option: "-y" },
      { option: "-async", argument: "1" }
    ],
    metadata: { duration: true, filesize: true },
    id: `ch${seg.chapter_number || 0}_seg${seg.segment_number || 0}_${seg.scene_type || "seg"}.mp4`
  }
};

/**
 * Build batched FFmpeg concat requests safely
 */
function buildComposeConcatBatched(fileUrls, opts = {}) {
  const {
    batchSize = 10,           // max inputs per batch
    targetFps = 30,
    sampleRate = 48000,
    channels = "stereo",
    crf = 20,
    preset = "veryfast",
    audioBitrate = "192k",
    outputPrefix = "youtube-automation/concat_batch_",
    finalOutput = "youtube-automation/final_concat_output.mp4"
  } = opts;

  if (!Array.isArray(fileUrls) || fileUrls.length === 0)
    throw new Error("No input files provided.");

  // Split input list into smaller chunks
  function chunkArray(arr, size) {
    const chunks = [];
    for (let i = 0; i < arr.length; i += size) chunks.push(arr.slice(i, i + size));
    return chunks;
  }

  const batches = chunkArray(fileUrls, batchSize);
  const batchJobs = [];

  // ---- STEP 1: Create a concat job for each batch ----
  for (let b = 0; b < batches.length; b++) {
    const urls = batches[b];
    const n = urls.length;
    const inputs = urls.map(u => ({ file_url: u }));

    // Build the concat expression dynamically
    const interleaved = [];
    for (let i = 0; i < n; i++) interleaved.push(`[${i}:v]`, `[${i}:a]`);
    const concatExpr = `${interleaved.join("")}concat=n=${n}:v=1:a=1[v][a];[v]fps=${targetFps},format=yuv420p[v]`;

    const outputs = [
      {
        options: [
          { option: "-filter_complex", argument: concatExpr },
          { option: "-map", argument: "[v]" },
          { option: "-map", argument: "[a]" },
          { option: "-c:v", argument: "libx264" },
          { option: "-preset", argument: preset },
          { option: "-crf", argument: String(crf) },
          { option: "-fps_mode", argument: "vfr" },
          { option: "-c:a", argument: "aac" },
          { option: "-b:a", argument: String(audioBitrate) },
          { option: "-ar", argument: String(sampleRate) },
          { option: "-ac", argument: channels === "stereo" ? "2" : "1" },
          { option: "-movflags", argument: "+faststart" }
        ]
      }
    ];

    const global_options = [
      { option: "-y" },
      { option: "-async", argument: "1" }
    ];

    batchJobs.push({
      inputs,
      outputs,
      global_options,
      metadata: { duration: true, filesize: true },
      id: `${outputPrefix}${b + 1}.mp4`
    });
  }

  // ---- STEP 2: Create the final concat job ----
  const finalInputs = batchJobs.map(j => ({ file_url: `http://host.docker.internal:9000/${j.id}` }));
  const finalInterleaved = [];
  for (let i = 0; i < finalInputs.length; i++) finalInterleaved.push(`[${i}:v]`, `[${i}:a]`);
  const finalExpr = `${finalInterleaved.join("")}concat=n=${finalInputs.length}:v=1:a=1[v][a];[v]fps=${targetFps},format=yuv420p[v]`;

  const finalJob = {
    inputs: finalInputs,
    outputs: [
      {
        options: [
          { option: "-filter_complex", argument: finalExpr },
          { option: "-map", argument: "[v]" },
          { option: "-map", argument: "[a]" },
          { option: "-c:v", argument: "libx264" },
          { option: "-preset", argument: preset },
          { option: "-crf", argument: String(crf) },
          { option: "-c:a", argument: "aac" },
          { option: "-b:a", argument: String(audioBitrate) },
          { option: "-ar", argument: String(sampleRate) },
          { option: "-ac", argument: channels === "stereo" ? "2" : "1" },
          { option: "-movflags", argument: "+faststart" }
        ]
      }
    ],
    global_options: [
      { option: "-y" },
      { option: "-async", argument: "1" }
    ],
    metadata: { duration: true, filesize: true },
    id: finalOutput
  };

  return { batchJobs, finalJob };
}

